// The satellite feature is built on a pun (Pie in the Sky: pies are satellites, crusts their orbital shells, a baked shell a full one); in serious
// English it says satellites and shells. Whole words only, so a network slice or a pizza stays what it is.
const SERIOUS_SAT=[[/\bPies in the [Ss]ky\b/g,'Satellites in orbit'],[/\bpies in the sky\b/g,'satellites in orbit'],[/\bPie in the Sky\b/g,'Satellites'],[/\bpie in the sky\b/g,'satellites'],
  [/\bPies\b/g,'Satellites'],[/\bpies\b/g,'satellites'],[/\bPie\b/g,'Satellite'],[/\bpie\b/g,'satellite'],
  [/\bCrusts\b/g,'Shells'],[/\bcrusts\b/g,'shells'],[/\bCrust\b/g,'Shell'],[/\bcrust\b/g,'shell'],
  [/\bHalf-baked\b/g,'Partly complete'],[/\bhalf-baked\b/g,'partly complete'],[/\bBaked\b/g,'Complete'],[/\bbaked\b/g,'complete'],[/\bbake\b/g,'build']];
// {placeholders} are left alone: a {crust} the game fills in must stay {crust}.
const seriousSat=v=>typeof v!=='string'?v:v.split(/(\{\w+\})/).map((part,i)=>i%2?part:SERIOUS_SAT.reduce((t,[re,to])=>t.replace(re,to),part)).join('');
(()=>{let on=false;try{on=!!JSON.parse(localStorage.getItem('sot-prefs')||'{}').serious;}catch(e){}if(!on||LANG!=='en')return;
  Object.assign(DICT,SERIOUS_EN);
  for(const k in DICT){const o=DICT[k];if(typeof o==='string'){if(/\b(?:[Pp]ies?|[Cc]rusts?|[Bb]aked?|[Hh]alf-baked)\b/.test(o))DICT[k]=seriousSat(o);}
    else if(o&&typeof o==='object'&&/\b(?:[Pp]ies?|[Cc]rusts?|[Bb]aked?|[Hh]alf-baked)\b/.test(o.one+o.other))DICT[k]={...o,one:seriousSat(o.one),other:seriousSat(o.other)};}})();
